fn reference_check(b:&[u8])->Result<(),CodecError>{
 let mut i=0;while i<b.len()/16 {for j in 0..4 {
  let n=u32::from_le_bytes(b[16*i+4*j..16*i+4*j+4].try_into().unwrap());
