fn full_input()->(Prepared,Accumulator){
 let p=Prepared{variant:Variant::S2,roots:kani::any(),gamma:any_e(),kappa:any_e(),alpha:[any_e(),any_e()],rho:any_k(),queries:kani::any(),semantic_alpha:core::array::from_fn(|_|any_k()),z:core::array::from_fn(|_|SecureCirclePoint{x:any_k(),y:any_k()}),claim:any_e(),state:kani::any()};
 let mut weights=Vec::with_capacity(64);for _ in 0..64{weights.push(any_k());}
 let a=Accumulator{weights,rhs:any_e(),power:any_k(),next:kani::any()};(p,a)
}
#[derive(Clone,Copy)] pub(crate) struct Ordered<'a>{pub(crate) count:&'a core::cell::Cell<usize>,pub(crate) proof:&'a[u8],pub(crate) public:&'a[u8],pub(crate) answers:[[u8;32];3]}
impl Digest32 for Ordered<'_>{fn digest(&self,parts:&[&[u8]])->[u8;32]{let i=self.count.get();assert!(i<3);match i{0=>{assert_eq!(parts.len(),1);assert_eq!(parts[0],self.proof);},1=>{assert_eq!(parts.len(),1);assert_eq!(parts[0],self.public);},2=>{assert_eq!(parts.len(),2);assert_eq!(parts[0],b"UNPROVED:R1:checkpoint");assert_eq!(parts[1].len(),1736);},_=>unreachable!()};self.count.set(i+1);self.answers[i]}}
fn checkpoint_stage(stage:usize){let(p,a)=full_input();let proof:[u8;3]=kani::any();let public:[u8;5]=kani::any();let answers:[[u8;32];3]=kani::any();let count=core::cell::Cell::new(0);let out=verifier::checkpoint(&p,&a,&proof,&public,Ordered{count:&count,proof:&proof,public:&public,answers});assert_eq!(count.get(),3);assert_eq!(out.len(),1768);
 let j:usize=kani::any();match stage{
 0=>{kani::assume(j<16);let expected=if j<8{b"R1P2CKP2"[j]}else{[p.variant.tag(),a.next as u8,1,0,0,0,0,0][j-8]};assert_eq!(out[j],expected);},
 1=>{kani::assume(j<32);assert_eq!(out[16+j],answers[0][j]);},
 2=>{kani::assume(j<32);assert_eq!(out[48+j],answers[1][j]);},
 3=>{kani::assume(j<32);assert_eq!(out[80+j],p.state[j]);},
 4=>{kani::assume(j<64);assert_eq!(out[112+j],p.roots[j/32][j%32]);},
 5=>{kani::assume(j<88);assert_eq!(out[320+j],p.queries[j/4].to_le_bytes()[j%4]);},
 6=>{kani::assume(j<128);let es=[p.gamma,p.kappa,p.alpha[0],p.alpha[1]];assert_eq!(out[176+j],es[j/32].to_limbs()[(j%32)/4].to_le_bytes()[j%4]);},
 7=>{kani::assume(j<1024);assert_eq!(out[712+j],limbs(a.weights[j/16])[(j%16)/4].to_le_bytes()[j%4]);},
 _=>{kani::assume(j<32);assert_eq!(out[1736+j],answers[2][j]);}}
 kani::cover!(j==0);
}
