                    pool: common.master_account,
                    asset_mint: [5; 32],
                    token_program: [6; 32],
                    asset_id: M31(77),
                    deployment_domain: source.deployment_domain,
                },
                verifier_policy: VerifierPolicyV1 {
                    flags: 1,
                    registry_program: [7; 32],
                    registry_authority: [0; 32],
